insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_2_v1'
from (values
('114.35.c.1.A',2,'In ASL II, partners sign about weekend plans. Which purpose does this exchange serve?','["socializing and exchanging information", "memorizing the periodic table", "measuring angles", "timing a sprint"]'::jsonb,0,'Level II students use learned material to talk with others.','original'),
('114.35.c.1.A',3,'Which skill grows most when ASL II students practice signed conversations in pairs?','["musical rhythm", "expressive and receptive signing", "map reading", "mathematical estimation"]'::jsonb,1,'Pair practice builds both signing and understanding.','original'),
('114.35.c.1.B',3,'An ASL II student watches a signed story and then explains the main events. This shows:','["knowledge of chemistry", "skill with spelling in English only", "comprehension of signed stories", "skill with calculation"]'::jsonb,2,'Understanding stories and instructions is a Level II goal.','original'),
('114.35.c.1.B',3,'Which signed message would an ASL II student be expected to understand?','["a technical engineering lecture", "a legal argument in a courtroom", "a medical research report", "a set of everyday instructions"]'::jsonb,3,'Level II comprehension covers stories, commands and instructions.','original'),
('114.35.c.1.C',3,'A signer uses facial expression, handshape and movement to show a car turning a corner. These are:','["classifiers combined with grammar", "audio cues", "written English words", "only fingerspelled letters"]'::jsonb,0,'Classifiers show how objects move.','original'),
('114.35.c.1.C',3,'When conveying information in ASL, why do signers use clear phrases and sentences?','["to sign more slowly than anyone", "to be understood without extra help", "to avoid eye contact", "to switch to spoken English"]'::jsonb,1,'The goal is to communicate meaning without assistance.','original'),
('114.35.c.1.D',3,'The study of how signs are built from smaller meaningful parts, such as added movement, is called:','["syntax", "semantics", "morphology", "pragmatics"]'::jsonb,2,'Morphology concerns word formation.','original'),
('114.35.c.1.D',3,'Pragmatics in ASL refers to:','["the speed of fingerspelling only", "the shape of a letter", "the brightness of a room", "using signs appropriately in social situations"]'::jsonb,3,'Pragmatics covers appropriate use in context.','original'),
('114.35.c.1.E',3,'A student creating an ASL handshape story is expected to follow:','["traditional features of ASL literature", "rules for map drawing", "rules for music notation", "rules for English rhymes"]'::jsonb,0,'Created stories follow Deaf literary traditions.','original'),
('114.35.c.1.E',3,'Creating and expressing ASL literature means the student:','["only copies an English song", "produces an original signed story or poem", "only reads a printed poem", "only watches a video"]'::jsonb,1,'Creation is part of the Level II standard.','original'),
('114.35.c.2.A',3,'Explaining in writing or in ASL how Deaf people get each other''s attention shows understanding of:','["chemical bonds", "geometric proofs", "Deaf cultural norms", "musical scales"]'::jsonb,2,'Norms guide respectful interaction.','original'),
('114.35.c.2.A',3,'Which practice is a Deaf cultural norm in a group conversation?','["looking away", "talking over signers", "turning lights off while signing", "keeping a clear line of sight to everyone signing"]'::jsonb,3,'Visual access is essential in Deaf communication.','original'),
('114.35.c.2.B',3,'Learning ASL poetry created by Deaf artists helps students see how literature expresses:','["the values of Deaf culture", "rules of baseball", "tax law", "steps of a chemical lab"]'::jsonb,0,'Literature reflects cultural perspectives.','original'),
('114.35.c.2.B',3,'Which activity shows appreciation of ASL literature?','["changing the subject", "discussing the meaning of a signed narrative", "leaving class", "ignoring it"]'::jsonb,1,'Discussion shows engagement with literature.','original'),
('114.35.c.2.C',3,'Deaf individuals have contributed to arts and sciences. Learning about this shows students:','["Deaf people cannot work in science", "art has no cultural source", "Deaf people have made important achievements", "only hearing people create art"]'::jsonb,2,'Contributions broaden students'' respect.','original'),
('114.35.c.2.C',3,'Researching a Deaf artist or scientist helps connect ASL study to:','["random trivia", "unrelated fantasy", "nothing at all", "real contributions in the community"]'::jsonb,3,'Biographies make culture concrete.','original'),
('114.35.c.2.D',3,'Why do ASL II students study Deaf history?','["to understand how events shaped Deaf perspectives", "to memorize dates only", "to avoid current issues", "to practice math"]'::jsonb,0,'History connects to present-day views.','original'),
('114.35.c.2.D',3,'A timeline of Deaf education milestones is an example of:','["a recipe", "organizing Deaf history", "a periodic table", "a weather chart"]'::jsonb,1,'Timelines help students understand history.','original'),
('114.35.c.3.A',3,'An ASL II student uses an online dictionary of signs. This is an example of:','["copying a friend''s work", "avoiding technology", "using digital resources for ASL information", "skipping research"]'::jsonb,2,'Digital resources support learning.','original'),
('114.35.c.3.A',3,'Which source is most reliable for information about Deaf culture?','["a random comment", "an unrelated advertisement", "an anonymous rumor", "a national Deaf organization"]'::jsonb,3,'Reliable sources come from the community.','original'),
('114.35.c.3.B',3,'A student uses ASL to explain a science concept to a partner. This shows ASL being used to:','["reinforce knowledge in another subject", "memorize signs without meaning", "stop learning ASL", "avoid the subject"]'::jsonb,0,'ASL can support other subjects.','original'),
('114.35.c.3.B',3,'Signing the steps of a math problem helps a student:','["guess the answer", "expand knowledge in math through ASL", "skip class", "avoid math"]'::jsonb,1,'Content learning can be done through ASL.','original'),
('114.35.c.4.A',3,'Comparing how questions are marked in ASL and in English shows students:','["English has no rules", "ASL has no rules", "each language has its own rules", "ASL and English are identical"]'::jsonb,2,'Comparison builds language awareness.','original'),
('114.35.c.4.A',3,'Eyebrow position that marks a yes/no question in ASL is a:','["vocabulary word only", "decoration only", "random habit", "grammatical feature"]'::jsonb,3,'Facial grammar carries meaning.','original'),
('114.35.c.4.B',3,'Comparing holiday customs of Deaf and hearing communities shows students:','["similarities and differences between cultures", "that holidays are unimportant", "that customs do not exist", "that cultures are identical"]'::jsonb,0,'Cultural comparison deepens understanding.','original'),
('114.35.c.4.B',3,'Which question would help a student compare Deaf culture with their own?','["Which metal is lightest?", "How do people greet each other in each group?", "How fast can a car go?", "What is a prime number?"]'::jsonb,1,'Greeting customs are cultural practices.','original'),
('114.35.c.4.C',3,'Many English speakers use gestures that came from signing communities. This shows:','["that ASL cannot be learned", "that gestures are never shared", "languages and cultures can influence each other", "nothing about language"]'::jsonb,2,'Influence runs both ways.','original'),
('114.35.c.4.C',3,'A Deaf community''s use of new technology can change how its language is shared. This is an example of:','["technology having no effect", "signs being banned", "language never changing", "culture and language being influenced by change"]'::jsonb,3,'Language adapts to new tools.','original'),
('114.35.c.5.A',3,'An ASL II student volunteers to sign at a school event. This is:','["using ASL outside the classroom", "avoiding practice", "a written test", "a science project"]'::jsonb,0,'Real use builds proficiency.','original'),
('114.35.c.5.A',3,'At the novice-to-intermediate level, a student can:','["lecture on linguistics", "handle familiar topics with simple connected signing", "translate a novel", "interpret a legal trial"]'::jsonb,1,'This level covers familiar topics.','original'),
('114.35.c.5.B',3,'Which tool lets a Deaf person and a hearing person communicate through a signer on a screen?','["a radio", "a metronome", "video relay service", "a landline voice-only phone"]'::jsonb,2,'Video relay uses video to connect callers.','original'),
('114.35.c.5.B',3,'Texting and video chat help students communicate with the Deaf community by:','["blocking contact", "adding noise", "removing visuals", "providing quick, accessible contact"]'::jsonb,3,'Technology expands communication.','original'),
('114.35.c.5.C',3,'A lifelong ASL learner at the novice-to-intermediate level might:','["attend Deaf community events", "hide from signers", "stop practicing", "avoid new signs"]'::jsonb,0,'Participation supports ongoing learning.','original'),
('114.35.c.5.C',3,'Which habit shows someone becoming a lifelong ASL learner?','["forgetting vocabulary on purpose", "practicing signing regularly for enjoyment", "never signing outside class", "practicing only before tests"]'::jsonb,1,'Lifelong learners keep using the language.','original'),
('114.36.c.1.A',3,'In ASL III, a student leads a signed discussion about school events. This is an example of:','["a lab report", "a spelling drill", "an extended ASL exchange", "a map exercise"]'::jsonb,2,'Level III exchanges are more detailed and sustained.','original'),
('114.36.c.1.A',3,'Which describes the difference in an ASL III exchange compared with Level I?','["no signing at all", "only fingerspelling letters", "only single signs", "longer, more detailed signed conversation"]'::jsonb,3,'Higher levels use fuller, more complex signing.','original'),
('114.36.c.1.B',3,'Understanding a multi-step set of signed commands without repetition shows:','["stronger comprehension of ASL", "guessing", "no comprehension", "difficulty with signing"]'::jsonb,0,'Intermediate students handle longer signed input.','original'),
('114.36.c.1.B',3,'At Level III, which signed material might a student understand when dealing with others?','["a technical manual in another language", "a detailed story or a set of commands", "an advanced physics lecture", "a legal brief"]'::jsonb,1,'This level handles stories, commands and instructions.','original'),
('114.36.c.1.C',3,'Using spatial referencing to show where people sit in a room is part of:','["writing a paragraph", "spelling English words", "conveying information with concepts and classifiers", "reading aloud"]'::jsonb,2,'Space is used grammatically in ASL.','original'),
('114.36.c.1.C',3,'An intermediate signer describes a process using classifiers, phrases and sentences. The goal is to:','["avoid describing", "use spoken words", "confuse the audience", "be understood by others without assistance"]'::jsonb,3,'Clarity without help is the aim.','original'),
('114.36.c.1.D',3,'Which part of ASL grammar is concerned with the meaning of signs?','["semantics", "syntax", "morphology", "phonology"]'::jsonb,0,'Semantics is about meaning.','original'),
('114.36.c.1.D',3,'A signer''s choice of formal or casual signing for a different audience is a matter of:','["phonology", "pragmatics", "morphology", "spelling"]'::jsonb,1,'Pragmatics covers use in social context.','original'),
('114.36.c.1.E',3,'An ASL III student performs an original handshape story. To meet expectations the story should:','["be written only", "use only spoken rhyme", "follow traditional features of ASL literature", "avoid handshapes"]'::jsonb,2,'Original work still follows tradition.','original'),
('114.36.c.1.E',3,'Expressing ASL literature at Level III includes:','["only drawing maps", "only counting signs", "only reading English books", "performing signed poems or narratives"]'::jsonb,3,'Performance expresses literature.','original'),
('114.36.c.2.A',3,'Applying ASL to explain Deaf cultural norms means the student:','["signs an explanation of those norms", "avoids the topic", "writes in another language only", "only watches"]'::jsonb,0,'Application uses the language itself.','original'),
('114.36.c.2.A',3,'In Deaf culture, it is respectful to explain a reason before leaving a signed conversation. This is an example of a:','["math rule", "cultural norm", "chemical law", "geographic fact"]'::jsonb,1,'Norms guide courteous behavior.','original'),
('114.36.c.2.B',3,'Signing a response to an ASL poem shows:','["a spelling skill", "no engagement", "appreciation of ASL literature", "dislike of culture"]'::jsonb,2,'Responding in ASL demonstrates appreciation.','original'),
('114.36.c.2.B',3,'Analyzing why a Deaf storyteller chose a specific handshape reveals:','["nothing about culture", "math patterns", "only English grammar", "how literature reflects Deaf perspectives"]'::jsonb,3,'Analysis links form to culture.','original'),
('114.36.c.2.C',3,'An ASL III student signs a short report about a Deaf inventor. This shows:','["appreciation of Deaf contributions to arts and sciences", "disinterest", "avoidance of research", "spelling practice only"]'::jsonb,0,'Reports apply ASL to study contributions.','original'),
('114.36.c.2.C',3,'Contributions of Deaf people in the arts include:','["only sports", "signed performance and visual art", "only music written for the hearing", "none"]'::jsonb,1,'Deaf artists have enriched the arts.','original'),
('114.36.c.2.D',3,'An in-depth study of Deaf history includes learning about:','["unrelated trivia", "only one date", "major events and how they shaped Deaf identity", "a single sign"]'::jsonb,2,'Depth means causes and effects.','original'),
('114.36.c.2.D',3,'Why is in-depth knowledge of Deaf history useful to a signer?','["it prevents communication", "it is unrelated to culture", "it replaces ASL practice", "it explains present-day values and issues"]'::jsonb,3,'History informs the present.','original'),
('114.36.c.3.A',3,'Using a database or archive to gather in-depth information about Deaf culture is an example of:','["using digital resources for research", "copying", "avoiding sources", "guessing"]'::jsonb,0,'Digital archives support in-depth research.','original'),
('114.36.c.3.A',3,'A reliable source for in-depth information on ASL is:','["an unverified rumor", "a university or Deaf organization resource", "a joke website", "an anonymous post"]'::jsonb,1,'Credible sources matter.','original'),
('114.36.c.3.B',3,'An intermediate signer explains a history lesson in ASL. This shows ASL being used to:','["learn only vocabulary", "avoid history", "expand knowledge in another subject", "stop signing"]'::jsonb,2,'ASL supports learning across subjects.','original'),
('114.36.c.3.B',3,'At the intermediate level, which task connects ASL to science?','["skipping the class", "copying notes silently", "ignoring the experiment", "signing an explanation of a simple experiment"]'::jsonb,3,'Content learning through ASL.','original'),
('114.36.c.4.A',3,'At the intermediate level, a student signs a comparison of ASL and English structure. This demonstrates understanding of:','["the nature of language", "the water cycle", "the stock market", "the weather"]'::jsonb,0,'Language comparison builds awareness.','original'),
('114.36.c.4.A',3,'Which difference between ASL and English is an example of language structure?','["English uses space for grammar", "ASL uses space and facial expression for grammar", "both are identical", "ASL has no grammar"]'::jsonb,1,'ASL uses visual grammar.','original'),
('114.36.c.4.B',3,'Signing a comparison between Deaf culture and your own culture shows an understanding of:','["coastlines", "the periodic table", "the nature of culture", "fractions"]'::jsonb,2,'Comparison highlights cultural features.','original'),
('114.36.c.4.B',3,'Which cultural difference might a student identify between Deaf and hearing communities?','["the number of days in a week", "the rules of chess", "the freezing point of water", "attention-getting strategies"]'::jsonb,3,'Attention strategies differ.','original'),
('114.36.c.4.C',3,'Signing an explanation of how English influenced ASL (and the reverse) shows understanding of:','["how one language and culture can influence another", "how weather changes", "how rocks form", "how plants grow"]'::jsonb,0,'Cross-influence is a Level III topic.','original'),
('114.36.c.4.C',3,'Fingerspelling borrowed English names into ASL. This is an example of:','["language loss", "language contact and influence", "language isolation", "no influence"]'::jsonb,1,'Languages borrow from each other.','original'),
('114.36.c.5.A',3,'An intermediate student interprets for a classmate during a school activity. This is an example of:','["an art lesson", "avoiding ASL", "applying ASL outside class", "a written quiz"]'::jsonb,2,'Real-world use builds skill.','original'),
('114.36.c.5.A',3,'At the intermediate proficiency level, a student can:','["not sign at all", "only sign the alphabet", "only copy signs", "discuss familiar and some new topics in ASL"]'::jsonb,3,'Intermediate means broader topics.','original'),
('114.36.c.5.B',3,'Which technology lets a signing student stay in touch with the Deaf community?','["video chat applications", "a paperclip", "a thermometer", "a flashlight"]'::jsonb,0,'Video technology supports signing.','original'),
('114.36.c.5.B',3,'Why does technology matter to the Deaf/ASL community?','["it hides information", "it connects signers across distance", "it removes visual communication", "it blocks signing"]'::jsonb,1,'Technology connects signers.','original'),
('114.36.c.5.C',3,'A lifelong ASL learner at the intermediate level might:','["avoid signing", "avoid Deaf events", "mentor beginning students", "quit after the course"]'::jsonb,2,'Mentoring continues learning.','original'),
('114.36.c.5.C',3,'Using ASL for personal enrichment at the intermediate level could include:','["deleting contacts", "ignoring ASL", "skipping events", "watching signed performances for enjoyment"]'::jsonb,3,'Enjoyment supports lifelong learning.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
